use vstd::prelude::*;

verus! {

spec fn sorted_nondecreasing(a: Seq<i32>) -> bool {
    forall|i: int, j: int|
        0 <= i <= j < a.len() ==> a[i] <= a[j]
}

spec fn first_occurrence_spec(a: Seq<i32>, target: i32, res: Option<usize>) -> bool {
    match res {
        Some(k) => {
            &&& (k as int) < a.len()
            &&& a[k as int] == target
            &&& forall|i: int| 0 <= i < (k as int) ==> a[i] != target
        }
        None => {
            forall|i: int| 0 <= i < a.len() ==> a[i] != target
        }
    }
}

fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> (index: Option<usize>)
    requires
        sorted_nondecreasing(arr@),
    ensures
        first_occurrence_spec(arr@, target, index),
{
    let mut lo: usize = 0;
    let mut hi: usize = arr.len();

    while lo < hi
        invariant
            lo <= hi,
            hi <= arr.len(),
            forall|i: int| 0 <= i < lo as int ==> arr@[i] < target,
            forall|i: int| hi as int <= i < arr@.len() ==> arr@[i] >= target,
    {
        let mid: usize = lo + (hi - lo) / 2;
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // Now lo == hi and is the first index with arr[i] >= target (if any).
    if lo < arr.len() && arr[lo] == target {
        Some(lo)
    } else {
        None
    }
}

} // verus!